page Login "/" {
  state email = ""
  state password = ""
  state logged = false
  computed valid = email.includes("@") && password.length >= 8

  fn submit() {
    if !valid { return }
    logged = true
  }

  column gap=4 pad=4 {
    if logged {
      title `Bienvenido, ${email}`
    } else {
      title "Iniciar sesión"
      form gap=3 -> submit() {
        input email type=email label="Email" placeholder="Email" required
        input password type=password label="Contraseña" placeholder="Contraseña" required
        button "Entrar" primary disabled=(!valid)
      }
    }
  }
}

