model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  state products: Product[] = [
    { id: "p1", name: "Remera", price: 15.5 },
    { id: "p2", name: "Zapatillas", price: 89.99 },
    { id: "p3", name: "Gorra", price: 9.9 }
  ]
  state cart: CartItem[] = []
  computed total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)
  computed count = cart.reduce((sum, i) => sum + i.qty, 0)

  fn add(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      cart = cart.map(i => i.id == p.id ? { id: i.id, name: i.name, price: i.price, qty: i.qty + 1 } : i)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn change(id, delta) {
    cart = cart
      .map(i => i.id == id ? { id: i.id, name: i.name, price: i.price, qty: i.qty + delta } : i)
      .filter(i => i.qty > 0)
  }

  column gap=4 pad=4 {
    title "Tienda"
    column gap=2 {
      text "Productos" bold
      for p in products key p.id {
        row gap=2 align=center {
          text p.name
          text `$${p.price.toFixed(2)}` muted
          button "Agregar" primary small -> add(p)
        }
      }
    }
    divider
    column gap=2 {
      text `Carrito (${count})` bold
      if cart.length == 0 {
        text "El carrito está vacío" muted
      } else {
        for i in cart key i.id {
          row gap=2 align=center {
            text i.name
            text `$${i.price.toFixed(2)}` muted
            button "-" small -> change(i.id, -1)
            text `${i.qty}`
            button "+" small -> change(i.id, 1)
            text `$${(i.price * i.qty).toFixed(2)}`
          }
        }
      }
      text `Total: $${total.toFixed(2)}` bold large
    }
  }
}

