model User {
  id: ID
  name: String min=1
  email: Email
}

api users: User

page Home "/" {
  state name = ""
  state email = ""
  state error = ""
  data users = api.users.list()

  fn add() {
    if !email.includes("@") {
      error = "Email inválido"
      return
    }
    error = ""
    try {
      await api.users.create({ name: name.trim(), email: email.trim() })
      name = ""
      email = ""
    } catch (e) {
      error = e.message
    }
  }

  fn remove(id) {
    await api.users.remove(id)
  }

  column gap=4 pad=4 {
    title "Usuarios"
    row gap=2 {
      input name placeholder="Nombre"
      input email placeholder="Email" -> add()
      button "Agregar" primary -> add()
    }
    if error != "" {
      text error danger
    }
    if users.length == 0 {
      text "No hay usuarios" muted
    } else {
      for u in users key u.id {
        row gap=2 align=center {
          text u.name bold
          text u.email muted
          button "Borrar" small danger -> remove(u.id)
        }
      }
    }
  }
}

