model Item {
  id: ID
  name: String min=1
  bought: Bool = false
}

api items: Item

page Home "/" {
  state draft = ""
  data items = api.items.list()
  computed pending = items.filter(i => !i.bought)

  fn add() {
    let name = draft.trim()
    if name == "" { return }
    draft = ""
    api.items.create({ name: name, bought: false })
  }

  fn buy(item) {
    api.items.update(item.id, { bought: true })
  }

  fn del(id) {
    api.items.remove(id)
  }

  column gap=4 pad=4 {
    title "Lista de compras"
    text `${pending.length} por comprar`
    row gap=2 {
      input draft placeholder="Producto" -> add()
      button "Agregar" primary -> add()
    }
    for i in items key i.id {
      row gap=2 align=center {
        text i.name muted=i.bought
        if i.bought {
          text "✓"
        }
        button "Comprado" small -> buy(i)
        button "Borrar" small danger -> del(i.id)
      }
    }
  }
}

