files.sim.ts:
export type Ball = { x: number; y: number; vx: number; vy: number; r: number }

export const W = 400
export const H = 300
const R = 10
const G = 0.2

export function make(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
    r: R,
  }
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += G
    b.x += b.vx
    b.y += b.vy
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
    if (b.x > W - b.r) { b.x = W - b.r; b.vx = -Math.abs(b.vx) }
    if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
    if (b.y > H - b.r) { b.y = H - b.r; b.vy = -Math.abs(b.vy) }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i]
      const b = balls[j]
      const dx = b.x - a.x
      const dy = b.y - a.y
      const min = a.r + b.r
      const d2 = dx * dx + dy * dy
      if (d2 < min * min) {
        const d = Math.sqrt(d2) || 0.0001
        const nx = dx / d
        const ny = dy / d
        const overlap = min - d
        a.x -= (nx * overlap) / 2
        a.y -= (ny * overlap) / 2
        b.x += (nx * overlap) / 2
        b.y += (ny * overlap) / 2
        // mantener dentro del canvas tras separar
        for (const p of [a, b]) {
          p.x = Math.min(Math.max(p.x, p.r), W - p.r)
          p.y = Math.min(Math.max(p.y, p.r), H - p.r)
        }
        // intercambio de velocidades solo si se acercan
        const rel = (a.vx - b.vx) * nx + (a.vy - b.vy) * ny
        if (rel > 0) {
          const tx = a.vx, ty = a.vy
          a.vx = b.vx; a.vy = b.vy
          b.vx = tx; b.vy = ty
        }
      }
    }
  }
}

export function draw(cv: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!cv) return
  const ctx = cv.getContext("2d")
  if (!ctx) return
  ctx.clearRect(0, 0, cv.width, cv.height)
  ctx.fillStyle = "#1e293b"
  ctx.fillRect(0, 0, cv.width, cv.height)
  ctx.fillStyle = "#38bdf8"
  for (const b of balls) {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

files.app.art:
use "./sim.ts" { make, step, draw }

page Sim "/" {
  state balls: Any[] = []
  state frames = 0
  state paused = false
  ref cv
  fn tick() {
    if !paused {
      step(balls)
      draw(cv, balls)
      frames++
    }
    requestAnimationFrame(tick)
  }
  fn add() {
    balls.push(make())
    draw(cv, balls)
  }
  fn reset() {
    balls = Array.from({ length: 5 }, () => make())
    frames = 0
    draw(cv, balls)
  }
  mount {
    balls = Array.from({ length: 5 }, () => make())
    requestAnimationFrame(tick)
  }

  column gap=2 {
    canvas ref=cv id="sim" width=400 height=300
    text `Pelotas: ${balls.length}`
    text `Cuadros: ${frames}`
    row gap=2 {
      button "Agregar" -> add()
      button paused ? "Reanudar" : "Pausar" -> paused = !paused
      button "Reiniciar" -> reset()
    }
  }
}

