  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i]
      const b = balls[j]
      const dx = b.x - a.x
      const dy = b.y - a.y
      const minDist = a.r + b.r
      const d2 = dx * dx + dy * dy
      if (d2 < minDist * minDist) {
        const d = Math.sqrt(d2) || 0.0001
        const nx = dx / d
        const ny = dy / d
        // separar para que no queden solapadas
        const overlap = (minDist - d) / 2
        a.x -= nx * overlap
        a.y -= ny * overlap
        b.x += nx * overlap
        b.y += ny * overlap
        // mantener dentro del canvas
        for (const p of [a, b]) {
          p.x = Math.min(Math.max(p.x, p.r), W - p.r)
          p.y = Math.min(Math.max(p.y, p.r), H - p.r)
        }
        // intercambio de velocidades solo si se acercan
        const rvx = b.vx - a.vx
        const rvy = b.vy - a.vy
        if (rvx * nx + rvy * ny < 0) {
          const tvx = a.vx
          const tvy = a.vy
          a.vx = b.vx
          a.vy = b.vy
          b.vx = tvx
          b.vy = tvy
        }
      }
    }
  }
}

export function draw(cv: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!cv) return
  const ctx = cv.getContext("2d")
  if (!ctx) return
  ctx.clearRect(0, 0, W, H)
  ctx.fillStyle = "#1e1e2e"
  ctx.fillRect(0, 0, W, H)
  ctx.fillStyle = "#4f8cff"
  for (const b of balls) {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

