use "./sim.ts" { make, step, draw }

page Sim "/" {
  state balls: Any[] = []
  state frames = 0
  state paused = false
  ref cv
  fn tick() {
    if !paused {
      step(balls)
      draw(cv, balls)
      frames++
    }
    requestAnimationFrame(tick)
  }
  fn add() {
    balls.push(make())
    draw(cv, balls)
  }
  fn reset() {
    balls = Array.from({ length: 5 }, () => make())
    frames = 0
    draw(cv, balls)
  }
  mount {
    balls = Array.from({ length: 5 }, () => make())
    requestAnimationFrame(tick)
