model Vote {
  id: ID
  choice: String min=1
}

api votes: Vote

server fn vote(choice) {
  if choice != "dogs" && choice != "cats" {
    fail("Opción inválida")
  }
  db.votes.create({ choice: choice })
  return true
}

server fn results() {
  let all = db.votes.list()
  let dogs = all.filter(v => v.choice == "dogs").length
  let cats = all.filter(v => v.choice == "cats").length
  let total = dogs + cats
  return {
    dogs: dogs,
    cats: cats,
    dogsPct: total == 0 ? 0 : Math.round(dogs * 100 / total),
    catsPct: total == 0 ? 0 : Math.round(cats * 100 / total)
  }
}

server fn resetVotes() {
  let all = db.votes.list()
  for (const v of all) {
    db.votes.remove(v.id)
  }
  return true
}

page Poll "/" {
