  state error = ""

  fn refresh() {
    try {
      stats = await server.results()
    } catch (e) {
      error = e.message
    }
  }

  fn castVote(choice) {
    try {
      await server.vote(choice)
      error = ""
    } catch (e) {
      error = e.message
    }
    await refresh()
  }

  fn clearAll() {
    try {
      await server.resetVotes()
      error = ""
    } catch (e) {
      error = e.message
    }
    await refresh()
