model Product {
  id: ID
  name: String min=1
  number: Number
}

api products: Product

page Catalog "/" {
  state search = ""
  state page = 0
  state items: Product[] = []
  state total = 0
  state seeding = false
  ref seq = 0

  fn load() {
    seq = seq + 1
    let mine = seq
    let s = search
    let p = page
    api.products.list({ search: s, sort: "number", limit: 5, offset: p * 5 }).then(rows => {
      if mine == seq { items = rows }
    })
    api.products.count({ search: s }).then(n => {
      if mine == seq { total = n }
    })
  }

  fn seed() {
    if seeding { return }
    seeding = true
    api.products.count().then(async n => {
      if n == 0 {
        for (let i = 1; i <= 12; i++) {
          await api.products.create({ name: `Producto ${i}`, number: i })
        }
      }
      seeding = false
      page = 0
      load()
    })
  }

  effect {
    search
    page = 0
  }

  effect {
    search
    page
    load()
  }

  column gap=4 pad=4 {
    title "Catálogo"
    button "Cargar ejemplos" primary disabled=seeding -> seed()
