    if product.stock > 0 {
      product.stock--
      let found = cart.find(i => i.product.id == product.id)
      if found {
        found.qty++
      } else {
        cart.push({ product, qty: 1 })
      }
    }
  }
  fn changeQty(id, delta) {
    let p = products.find(x => x.id == id)
    if p {
      if delta > 0 && p.stock < delta {
        return
      }
      p.stock -= delta
    }
    cart = cart.map(i => i.product.id == id ? { ...i, qty: i.qty + delta } : i).filter(i => i.qty > 0)
  }
  fn clearCart() {
    cart.forEach(i => i.product.stock += i.qty)
    cart = []
  }

  column gap=4 pad=4 {
    Header count=count
    Nav tab=tab onChange=(t => tab = t)
    if tab == "catalog" {
      Catalog products=products onAdd=add
    } else {
      CartView cart=cart onChangeQty=changeQty onClear=clearCart
    }
    Footer
  }
}

