files.employees.art:
component EmployeesPage {
  state items: Item[] = [
    { id: 1, name: "Alfa", amount: 10, active: true },
    { id: 2, name: "Beta", amount: 20, active: true },
    { id: 3, name: "Gama", amount: 30, active: false }
  ]
  fn add(name, amount) {
    items.push({ id: Date.now(), name, amount, active: true })
  }
  fn toggle(id) {
    items = items.map(i => i.id == id ? { id: i.id, name: i.name, amount: i.amount, active: !i.active } : i)
  }

  column gap=2 {
    title "Empleados"
    EmployeesForm onAdd=add
    EmployeesList items=items onToggle=toggle
  }
}

component EmployeesList(items: Item[], onToggle: Fn) {
  if items.length == 0 {
    text "Sin registros" muted
  } else {
    column gap=1 {
      for item in items {
        EmployeesRow item=item onToggle=onToggle
      }
    }
  }
}

component EmployeesRow(item: Item, onToggle: Fn) {
  row gap=2 {
    text item.name bold
    if !item.active {
      text "(inactivo)" muted
    }
    text `Sueldo: ${item.amount}`
    button "Alternar" small -> onToggle(item.id)
  }
}

component EmployeesForm(onAdd: Fn) {
  state name = ""
  state amount = 0
  fn submit() {
    onAdd(name, amount)
    name = ""
    amount = 0
  }

  row gap=2 {
    input name placeholder="Nombre"
    input amount placeholder="Sueldo" type=number
    button "Agregar" primary -> submit()
  }
}

